events.command:
/bin/bash -lc "Rscript - <<'RS'
for (f in c('/workspace/tmp/res_GluFevsGluFePlus.rds','/workspace/tmp/res_SuccvsGluFePlus.rds')) {
  cat('\\nFILE', f, '\\n')
  x <- readRDS(f)
  cat('class', paste(class(x), collapse=','), '\\n')
  cat('typeof', typeof(x), 'length', length(x), '\\n')
  if (isS4(x)) { print(slotNames(x)); print(dim(x)); print(head(x)); print(colnames(x)) }
  else if (is.data.frame(x)) { print(dim(x)); print(head(x)); print(colnames(x)); print(rownames(head(x))) }
  else { print(str(x)); print(names(x)) }
}
RS"

